#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto doOp=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };
    for(int t=0;t<n-1;t++){
        int pos=-1;
        for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;
        // Move element from pos to position t
        // Step 1: move to position n-1
        if(pos!=n-1){
            // op(pos+1, n-1-pos): x+y = n, invalid
            // op(pos-t, n-1-pos): x=pos-t>0(since pos>t), y=n-1-pos>0(since pos<n-1)
            // x+y = pos-t+n-1-pos = n-1-t < n. Valid!
            // After: [p[pos+1..n-1]] [p[pos-t..pos]] [p[0..pos-t-1]]
            // But wait, elements [0..t-1] are already sorted. We're cutting x=pos-t from the front,
            // which includes p[t..pos-1] (the sorted prefix p[0..t-1] gets moved to middle or suffix).
            // Actually this destroys already placed elements. Need to keep prefix intact.
            // Use: x=pos+1, y=1 if pos+2<n: moves element at pos into the suffix (pos n-1)
            // Actually: x=pos-t, y=n-1-pos, this keeps p[0..t-1] in middle since t <= pos-t? No.
            // Let me just do: bring to end with x=pos+1-t, y=n-1-pos, but protect prefix by offsetting.
            // Hmm, prefix includes 0..t-1 which are correct. x=pos+1-t means cutting pos+1-t from start: ruins sorted part if t>0.
            // Safe approach: x=1, y=n-1-pos if 1+n-1-pos<n => pos>0 (true). Moves last elem but also moves sorted prefix.
            // I think I need to not try to preserve the sorted prefix and instead just sort the whole thing.
            int x=pos+1, y=1;
            if(x+y<n){ doOp(x,y); pos=n-1; }
            else{ x=pos; y=1; if(x>0&&x+y<n){doOp(x,y); pos=n-2;}}
        }
        for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;
        if(pos>t){
            int x=t+1, y=n-pos;
            if(x>0&&y>0&&x+y<n){ doOp(x,y); continue; }
            // fallback
            if(t+1>0&&1>0&&t+2<n){ doOp(t+1,1); }
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
